import HeroSection from '../../components/HeroSection/HeroSection';
import './Home.css';
import HeroBanner from '../../assets/banners/hero-banner.jpg';


// ⚠️ Більше не приймає пропси { products }
export default function Home() {

    // ⚠️ ВИДАЛЯЄМО ВСІ useState() для пошуку/сортування/ліміту

    // ⚠️ ВИДАЛЯЄМО ВСЮ ЛОГІКУ filtered, visibleProducts, handleViewMore

    return (
        <div className="home-container">

            <HeroSection />

            {/* Додаткова інформація про сайт */}
            <section className="about-section">
                <h2>Welcome to GadgetNew!</h2>
                <p>Натисніть на "Каталог", щоб переглянути всі наші товари, скористатися пошуком та фільтрацією.</p>
            </section>

            {/* ⚠️ ВИДАЛЯЄМО: search-sort-panel, products-grid, view-more-wrapper */}
        </div>
    );
}
